# Provision the Kohinoor accounts in the REAL Atlas database SiteVisionKohinoor.
#
# The connection string is decrypted from %USERPROFILE%\.sitevision-secrets\kohinoor_target.xml (Windows DPAPI) in memory,
# passed to the provisioning tool through an environment variable of the child process only, and never printed or logged.
# Passwords are generated by the tool and written ONLY to a new owner-only file in %USERPROFILE%\.sitevision-secrets.
# Dry run unless -Apply. Domain verification is NOT required (tenant routing keys on the configured e-mail domain); optional extras:
#   -RequireDomainVerification  refuse unless -DomainVerified (you attest) or -DomainTxtToken <token> (the owner published
#                               sitevision-verification=<token> as an apex TXT record) is also given
#   -DomainTxtToken <token>     if given, that TXT record must exist or the run is refused
param(
  [string]$AccountsFile = 'D:\Srivarshini.N\Backups\sitevision-recovery-20261029-1202\kohinoor-demo-accounts.json',
  [switch]$Apply,
  [switch]$DomainVerified,
  [switch]$RequireDomainVerification,
  [string]$DomainTxtToken = ''
)
$ErrorActionPreference = 'Stop'
$backend = Split-Path -Parent $PSScriptRoot
$f = Join-Path $env:USERPROFILE '.sitevision-secrets\kohinoor_target.xml'
if (-not (Test-Path $f)) { throw "Missing $f" }
$ss = Import-Clixml $f; $b = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($ss)
try { $env:SV_KOHINOOR_ATLAS_URI = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($b) } finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($b) }
$toolArgs = @('scripts/provision_tenant_admin.py', '--tenant', 'kohinoor', '--accounts-file', $AccountsFile, '--uri-env', 'SV_KOHINOOR_ATLAS_URI')
if ($Apply) { $toolArgs += '--apply' }
if ($DomainVerified) { $toolArgs += '--domain-verified' }
if ($RequireDomainVerification) { $toolArgs += '--require-domain-verification' }
if ($DomainTxtToken) { $toolArgs += @('--domain-txt-token', $DomainTxtToken) }
Push-Location $backend
try { & (Join-Path $backend '.venv\Scripts\python.exe') @toolArgs } finally { Pop-Location; Remove-Item Env:SV_KOHINOOR_ATLAS_URI -ErrorAction SilentlyContinue }
